# Strip HTML completely
from bs4 import BeautifulSoup
soup = BeautifulSoup(text, 'html.parser')
for tag in soup(["script", "style", "nav", "div"]):
    if tag.get("class") and "nsw-chapter-nav" in tag.get("class"):
        tag.decompose()

clean_text = soup.get_text()
arabic_chars = len(re.findall(r'[\u0600-\u06FF]', clean_text))
total_chars_clean = len(clean_text.strip())
total_chars_with_spaces = len(re.sub(r'<[^>]+>', ' ', text))
words = len(clean_text.split())

print("Exact Arabic Letters Count:", arabic_chars)
print("Clean Text Length (chars):", total_chars_clean)
print("Total Words:", words)
print("Raw Content Length (with HTML):", len(text))
